<?php
declare(strict_types=1);
require_once __DIR__.'/../app/helpers/auth.php';
require_once __DIR__.'/../app/config/database.php';
require_once __DIR__.'/../app/helpers/gyd_comparativo_sucursales.php';
requireLogin();
$user=currentUser()??[];
if(!gcs_role($user)){http_response_code(403);exit('Acceso reservado a Dirección y Administración.');}
header('Cache-Control: private, no-store, max-age=0');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: same-origin');
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){http_response_code(405);exit('Método no permitido.');}
$param=static function(string $key,string $fallback=''):string { $v=$_GET[$key]??$fallback;return is_string($v)?trim($v):$fallback; };
$today=new DateTimeImmutable('today');
$from=$param('desde',$today->modify('-6 days')->format('Y-m-d'));
$to=$param('hasta',$today->format('Y-m-d'));
$braw=$param('sucursal','0');$branch=filter_var($braw,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);
$export=$param('exportar');$data=null;$error='';
try{
 if($branch===false)throw new DomainException('Sucursal inválida.');
 if(!in_array($export,['','csv'],true))throw new DomainException('Exportación no permitida.');
 $data=gcs_report((new Database())->connect(),$from,$to,(int)$branch);
}catch(DomainException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Comparativo General de Sucursales: '.$e->getMessage());$error='No se pudo consultar alguno de los datos. Revisa los registros de PHP y el esquema de la base de pruebas.';}
if($data!==null && $export==='csv'){
 header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="G_D_Comparativo_Sucursales_'.$from.'_a_'.$to.'.csv"');
 $fp=fopen('php://output','wb');fwrite($fp,"\xEF\xBB\xBF");fwrite($fp,"sep=;\r\n");
 $write=static function(array $values)use($fp):void{fputcsv($fp,array_map('gcs_csv',$values),';','"','');};
 $write(['Farmacia G&D · Comparativo General de Sucursales']);$write(['Desde',$from,'Hasta',$to]);
 $write(['Neto: ventas originales pagadas en periodo menos devoluciones aplicadas en periodo; no se suman cajas a ventas.']);
 $write(['Sucursal','Ventas originales MXN','Devoluciones/cancelaciones MXN','Neto del periodo MXN','Tickets originales','Piezas originales','Tickets medidos','Tiempo promedio segundos','SKU con existencia registrada','SKU agotados','Piezas stock POS actual','Cortes cerrados','Turnos abiertos desde periodo','Faltantes MXN','Sobrantes MXN','Retiros POS MXN','Cobertura histórica costos %','Costo histórico original MXN','Utilidad bruta original estimada MXN','Margen bruto original %']);
 $money=static fn(?int $n)=>$n===null?'No disponible':number_format($n/100,2,'.','');
 foreach($data['rows'] as $r){$write([$r['nombre'],$money($r['ventas_c']),$money($r['reversiones_c']),$money($r['neto_c']),$r['tickets'],$r['piezas']??'N/D',$r['medidas']??'N/D',$r['tiempo_seg']??'N/D',$r['inventario_skus']??'N/D',$r['agotados']??'N/D',$r['piezas_stock']??'N/D',$r['turnos_cerrados'],$r['turnos_abiertos'],$money($r['faltante_c']),$money($r['sobrante_c']),$money($r['retiros_c']),$r['cobertura_costos']??'N/D',$money($r['costos_c']),$money($r['utilidad_c']),$r['margen_pct']??'N/D']);}
 $write([]);$write(['Productos más vendidos del periodo (por unidades)']);$write(['Producto','Piezas']);foreach(($data['top_productos']??[]) as $prod)$write([$prod['nombre'],$prod['piezas']]);$write([]);foreach($data['avisos'] as $notice)$write(['Nota',$notice]);fclose($fp);exit;
}
$rows=$data['rows']??[];$totalTickets=array_sum(array_column($rows,'tickets'));
$ventas=array_sum(array_column($rows,'ventas_c'));
$nets=$data && ($data['meta']['tiene_reversiones']??false)?array_sum(array_column($rows,'neto_c')):null;
$faltantes=array_sum(array_column($rows,'faltante_c'));
$sobrantes=array_sum(array_column($rows,'sobrante_c'));
$max=max(1,...array_map(static fn($r)=>max(0,(int)($r['neto_c']??$r['ventas_c'])),$rows));
$money=static fn(?int $n):string=>$n===null?'No disponible':gcs_money($n);
$qs=['desde'=>$from,'hasta'=>$to,'sucursal'=>(int)$branch];
?>
