<style>
:root{font:14px/1.55 system-ui,-apple-system,"Segoe UI",Arial,sans-serif;background:#f2f5fa;color:#1a2d48}*{box-sizing:border-box}body{margin:0}a{color:#1555a1}header{background:linear-gradient(115deg,#10294a,#1c5a99);color:#fff;padding:27px max(18px,calc((100vw - 1380px)/2)) 28px}.head{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap}.eyebrow{font-size:12px;letter-spacing:.09em;color:#b8daff;text-transform:uppercase;font-weight:800}h1{font-size:clamp(23px,3vw,32px);margin:5px 0}header p{margin:0;color:#d9e9fa}nav{display:flex;gap:8px;flex-wrap:wrap}nav a{color:#fff;border:1px solid #ffffff65;border-radius:9px;padding:8px 11px;text-decoration:none;font-weight:700}main{max-width:1420px;margin:0 auto;padding:20px 18px 50px}.panel{background:#fff;border:1px solid #dbe4ef;border-radius:13px;box-shadow:0 4px 15px #174d7d0a;padding:18px;margin-bottom:17px}h2{font-size:18px;margin:0 0 12px}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.filters label{display:grid;gap:5px;color:#425875;font-size:12px;font-weight:800}input,select{font:inherit;padding:10px 11px;border:1px solid #b7c8dc;border-radius:8px;min-height:42px;background:#fff;color:#1c314e}button,.btn{font:inherit;border:0;background:#1762a2;color:white;border-radius:8px;padding:10px 15px;min-height:42px;text-decoration:none;cursor:pointer;font-weight:800;display:inline-flex;align-items:center;justify-content:center}.btn.alt,button.alt{background:#eaf0f9;color:#174978}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.cards{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:11px;margin-bottom:16px}.card{background:white;border:1px solid #dbe4ef;border-radius:13px;padding:16px;min-width:0}.card span{color:#627795;font-size:12px}.card strong{display:block;font-size:clamp(18px,2vw,26px);margin-top:5px;letter-spacing:-.04em;overflow-wrap:anywhere}.card small{font-size:11px;color:#6c8199}.message{background:#fffaeb;border:1px solid #ebd5a2;border-radius:10px;padding:12px 14px;color:#634d20;margin-bottom:10px}.error{background:#fff2f3;border:1px solid #e4afb7;color:#872e3b;padding:14px;border-radius:10px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:16px}.bars{display:grid;gap:12px}.barTop{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px}.track{height:11px;background:#e9f0f7;border-radius:9px;overflow:hidden;margin-top:4px}.track>div{height:100%;background:linear-gradient(90deg,#2477b7,#37a0cf);border-radius:9px}.scroll{overflow:auto;width:100%}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}th{background:#f2f6fb;color:#47607d;text-align:left;font-size:12px}td,th{padding:11px 13px;border-bottom:1px solid #e5ebf3}td.number,th.number{text-align:right;font-variant-numeric:tabular-nums}tbody tr:hover{background:#f8fbff}.tag{display:inline-block;background:#edf3fa;color:#245785;border-radius:20px;padding:3px 9px;font-size:11px;font-weight:800}.muted{color:#60748d;font-size:12px}.empty{color:#667990;text-align:center;padding:28px}.note{font-size:12px;color:#5d6f84;line-height:1.6}.legend{display:flex;gap:15px;flex-wrap:wrap;font-size:12px;color:#64788f}.legend b{font-weight:750;color:#284664}@media(max-width:1100px){.cards{grid-template-columns:repeat(3,1fr)}.twocol{grid-template-columns:1fr}}@media(max-width:650px){.cards{grid-template-columns:repeat(2,1fr)}main{padding:12px}.panel{padding:13px}}@media print{header{background:white;color:#111;padding:0 0 12px}header p,.eyebrow{color:#333}nav,.filters,.toolbar,.noprint{display:none!important}main{padding:0}.cards{grid-template-columns:repeat(5,1fr)}.panel,.card{box-shadow:none;break-inside:avoid}.scroll{overflow:visible}table{font-size:10px;white-space:normal}td,th{padding:7px}.twocol{grid-template-columns:1fr 1fr}@page{size:A4 landscape;margin:9mm}}
</style></head><body>
<header><div class="head"><div><div class="eyebrow">Farmacia G&amp;D · Inteligencia operativa</div><h1>Comparativo General de Sucursales</h1><p>Ventas, productividad, inventario y control de cajas · Consulta de datos registrados</p></div><nav><a href="dashboard.php">Inicio</a><a href="erp_rendimiento_cajeros.php">Rendimiento</a><a href="erp_reportes_ventas_cajas.php">Ventas y cajas</a><a href="erp_alertas_gerenciales.php">Alertas</a></nav></div></header>
<main><section class="panel noprint"><h2>Filtros del comparativo</h2><form class="filters" method="get">
<label>Desde<input type="date" name="desde" value="<?=gcs_h($from)?>" required></label><label>Hasta<input type="date" name="hasta" value="<?=gcs_h($to)?>" required></label>
<label>Sucursal<select name="sucursal"><option value="0">Todas las sucursales</option><?php foreach(($data['branches']??[]) as $b):?><option value="<?=(int)$b['id']?>" <?=((int)$b['id']===(int)$branch)?'selected':''?>><?=gcs_h($b['nombre'])?></option><?php endforeach;?></select></label>
<button type="submit">Comparar</button><a class="btn alt" href="erp_comparativo_sucursales.php">Limpiar</a></form></section>
<?php if($error!==''):?><div class="error" role="alert"><?=gcs_h($error)?></div><?php else:?>
<div class="toolbar noprint"><a class="btn" href="?<?=gcs_h(http_build_query($qs+['exportar'=>'csv']))?>">Exportar Excel (CSV)</a><button type="button" class="alt" onclick="window.print()">Imprimir / Guardar PDF</button></div>
<section class="cards" aria-label="Resumen del periodo">
<div class="card"><span>Ventas originales</span><strong><?=gcs_h(gcs_money($ventas))?></strong><small>Por fecha de cobro</small></div>
<div class="card"><span>Venta neta del periodo</span><strong><?=gcs_h($money($nets))?></strong><small>Brutas menos reversiones del periodo</small></div>
<div class="card"><span>Tickets cobrados</span><strong><?=gcs_num($totalTickets)?></strong><small>Incluye tickets luego cancelados</small></div>
<div class="card"><span>Faltantes de caja</span><strong><?=gcs_h(gcs_money($faltantes))?></strong><small>Solo cortes cerrados del periodo</small></div>
<div class="card"><span>Sobrantes de caja</span><strong><?=gcs_h(gcs_money($sobrantes))?></strong><small>Se muestran separados de faltantes</small></div>
</section>
<div class="twocol"><section class="panel"><h2>Venta neta por sucursal</h2><div class="bars"><?php foreach($rows as $r):$value=$r['neto_c']??$r['ventas_c'];?><div><div class="barTop"><span><?=gcs_h($r['nombre'])?></span><strong><?=gcs_h($money($r['neto_c']))?></strong></div><div class="track"><div style="width:<?=round(100*max(0,$value)/$max,1)?>%"></div></div></div><?php endforeach;?><?php if(!$rows):?><p class="empty">Sin sucursales activas.</p><?php endif;?></div><p class="note">Barras de venta neta, si hay registro de reversiones. Si faltan, solo muestran magnitud de ventas originales, sin asignar un neto.</p></section>
<section class="panel"><h2>Rendimiento y cajas</h2><div class="scroll"><table><thead><tr><th>Sucursal</th><th class="number">Tickets</th><th class="number">Medidos</th><th class="number">Cobertura</th><th class="number">Tiempo promedio</th><th class="number">Cortes</th></tr></thead><tbody><?php foreach($rows as $r):$coverage=$r['medidas']===null||$r['tickets']===0?null:round(100*$r['medidas']/$r['tickets'],1);?><tr><td><?=gcs_h($r['nombre'])?></td><td class="number"><?=gcs_num($r['tickets'])?></td><td class="number"><?=($r['medidas']===null?'N/D':gcs_num($r['medidas']))?></td><td class="number"><?=$coverage===null?'N/D':gcs_h((string)$coverage).'%'?></td><td class="number"><?=$r['tiempo_seg']===null?'Sin medición':gcs_h(number_format($r['tiempo_seg'],1).' s')?></td><td class="number"><?=gcs_num($r['turnos_cerrados'])?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<section class="panel"><h2>Comparativo comercial y existencias</h2><div class="scroll"><table><thead><tr><th>Sucursal</th><th class="number">Ventas originales</th><th class="number">Devoluciones</th><th class="number">Venta neta</th><th class="number">Tickets</th><th class="number">Piezas vendidas</th><th class="number">SKU registrados</th><th class="number">SKU agotados</th><th class="number">Existencias POS actuales</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=gcs_h($r['nombre'])?></b></td><td class="number"><?=gcs_h(gcs_money($r['ventas_c']))?></td><td class="number"><?=gcs_h($money($r['reversiones_c']))?></td><td class="number"><b><?=gcs_h($money($r['neto_c']))?></b></td><td class="number"><?=gcs_num($r['tickets'])?></td><td class="number"><?=$r['piezas']===null?'N/D':gcs_num($r['piezas'])?></td><td class="number"><?=$r['inventario_skus']===null?'N/D':gcs_num($r['inventario_skus'])?></td><td class="number"><?=$r['agotados']===null?'N/D':gcs_num($r['agotados'])?></td><td class="number"><?=$r['piezas_stock']===null?'N/D':gcs_num($r['piezas_stock'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<div class="twocol"><section class="panel"><h2>Control de cajas por sucursal</h2><div class="scroll"><table><thead><tr><th>Sucursal</th><th class="number">Turnos cerrados</th><th class="number">Abiertos en periodo</th><th class="number">Retiros POS</th><th class="number">Faltantes</th><th class="number">Sobrantes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=gcs_h($r['nombre'])?></td><td class="number"><?=gcs_num($r['turnos_cerrados'])?></td><td class="number"><?=gcs_num($r['turnos_abiertos'])?></td><td class="number"><?=gcs_h($money($r['retiros_c']))?></td><td class="number"><?=gcs_h(gcs_money($r['faltante_c']))?></td><td class="number"><?=gcs_h(gcs_money($r['sobrante_c']))?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Rentabilidad con costos históricos</h2><div class="scroll"><table><thead><tr><th>Sucursal</th><th class="number">Cobertura costos</th><th class="number">Costo original</th><th class="number">Utilidad bruta original*</th><th class="number">Margen original*</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=gcs_h($r['nombre'])?></td><td class="number"><?=$r['cobertura_costos']===null?'N/D':gcs_h(number_format((float)$r['cobertura_costos'],1).'%')?></td><td class="number"><?=gcs_h($money($r['costos_c']))?></td><td class="number"><?=gcs_h($money($r['utilidad_c']))?></td><td class="number"><?=$r['margen_pct']===null?'N/D':gcs_h(number_format($r['margen_pct'],1).'%')?></td></tr><?php endforeach;?></tbody></table></div><p class="note">* Cálculo original sin reversión de costos ni gastos. Solo se muestra cuando el 100% de las partidas de ventas originales tiene costo histórico registrado. No equivale a utilidad neta.</p></section></div>
<section class="panel"><h2>Productos más vendidos por piezas</h2><p class="muted">Cantidad original de unidades vendidas en el periodo seleccionado; no es una tasa de rotación del inventario ni descuenta devoluciones.</p><div class="scroll"><table><thead><tr><th>Producto</th><th class="number">Piezas</th></tr></thead><tbody><?php foreach(($data['top_productos']??[]) as $product):?><tr><td><?=gcs_h($product['nombre'])?></td><td class="number"><?=gcs_num($product['piezas'])?></td></tr><?php endforeach;?><?php if(empty($data['top_productos'])):?><tr><td class="empty" colspan="2">Sin datos de unidades de venta disponibles.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><h2>Cómo interpretar estas cifras</h2><?php foreach($data['avisos'] as $notice):?><div class="message"><?=gcs_h($notice)?></div><?php endforeach;?><p class="note">Este panel no escribe en la base de datos y no sustituye los módulos de conciliación, inventario físico ni reportes contables. Todos los importes son en pesos mexicanos.</p></section>
<?php endif;?></main>
